//! Protobuf types of the whatsmeow port, generated by prost from the `.proto`
//! files under `proto/` (copied from whatsmeow's `proto/` tree).
//!
//! Modules carry prost's snake_case form of each proto package name. The
//! aliases at the bottom give every package the directory name whatsmeow's Go
//! code imports it by (`waE2E` → [`wa_e2e`]), so ported code reads like the Go.
#![deny(missing_docs)]

#[expect(
    missing_docs,
    clippy::large_enum_variant,
    clippy::module_inception,
    reason = "prost output for the vendored .proto files; the wire shapes are WhatsApp's"
)]
mod generated {
    include!(concat!(env!("OUT_DIR"), "/_includes.rs"));
}

pub use generated::*;

